if(route==='permissions'&&request.method==='POST'){if(typeof input.trading!=='boolean')throw Error('Choose whether to enable reviewed orders');await q('UPDATE trade_sessions SET trading = ? WHERE id = ? AND owner = ?',input.trading?1:0,sid,owner).run();return json({trading:input.trading})}
if(!session.trading)return json({error:'Reconnect with Enable order actions selected.'},403);
if(route==='review'&&request.method==='POST'){let pending=await q("SELECT id FROM trade_intents WHERE owner = ? AND symbol = ? AND status IN ('submitting','unknown')",owner,input.symbol).first();if(pending)throw Error('A previous request has an unconfirmed outcome. Check Delta directly before any new request for this coin.');let prepared=await prepareDelta(c,input),id=crypto.randomUUID().replaceAll('-',''),expires=Date.now()+60000;prepared.body.client_order_id=prepared.action==='open'||prepared.action==='close'?'r'+id.slice(0,30):undefined;await q('INSERT INTO trade_intents(id,owner,session,symbol,payload,status,expires) VALUES(?,?,?,?,?,?,?)',id,owner,sid,prepared.symbol,JSON.stringify({...prepared,strategy:prepared.action==='open'?(input.strategy==null?null:monitorStrategy(input.strategy)):null}),'review',expires).run();return json({id,expires,summary:prepared.summary})}
